"use client";

import { FlaskConical } from "lucide-react";

import { useSyntheticSymbols } from "@/hooks/use-market-data";
import { cn } from "@/lib/utils";

const EXPLANATION =
  "These prices were generated by the demo seed script so the app works offline. They are not real market data, and results built on them are illustrative only.";

/** Small inline tag for anything built on generated demo prices. Renders nothing for real data. */
export function SyntheticDataBadge({ symbols, className }: { symbols: string[]; className?: string }) {
  const synthetic = useSyntheticSymbols();
  if (!symbols.some((s) => synthetic.has(s))) return null;
  return (
    <span
      title={EXPLANATION}
      className={cn(
        "inline-flex items-center gap-1 rounded-full border border-warning/40 bg-warning/10 px-2 py-0.5 text-xs font-medium text-warning",
        className,
      )}
    >
      <FlaskConical aria-hidden className="h-3 w-3" />
      Synthetic demo data
    </span>
  );
}

/** Page-level notice, shown once wherever several panels draw on generated prices. */
export function SyntheticDataNotice({ className }: { className?: string }) {
  const synthetic = useSyntheticSymbols();
  if (synthetic.size === 0) return null;
  return (
    <p
      role="note"
      className={cn(
        "flex items-start gap-2 rounded-md border border-warning/40 bg-warning/10 px-4 py-3 text-sm text-foreground",
        className,
      )}
    >
      <FlaskConical aria-hidden className="mt-0.5 h-4 w-4 shrink-0 text-warning" />
      <span>
        <strong className="font-semibold">Synthetic demo data.</strong> Prices for {synthetic.size} symbols (such as{" "}
        {Array.from(synthetic).slice(0, 3).join(", ")}) were generated by the demo seed script, not downloaded from a
        market. Backtests built on them are illustrative only.
      </span>
    </p>
  );
}
